(()=>{'use strict';
const KEY='contademo_full_v1',NAV=[['inicio','Inicio'],['comprobantes','Comprobantes'],['compras','Compras'],['ventas','Ventas'],['retenciones','Retenciones'],['personal','Personal y planillas'],['informes','Informes'],['cuentas','Plan de cuentas'],['parametros','Parámetros'],['usuarios','Usuarios'],['bitacora','Bitácora']];
const seed=[['1.1.01','Caja','activo'],['1.1.02','Banco','activo'],['1.1.03','Cuentas por cobrar','activo'],['1.1.04','Inventario de mercadería','activo'],['1.1.05','Crédito fiscal IVA','activo'],['1.2.01','Muebles y equipos','activo'],['2.1.01','Cuentas por pagar','pasivo'],['2.1.02','Débito fiscal IVA','pasivo'],['2.1.03','IT por pagar','pasivo'],['2.1.04','IUE por pagar','pasivo'],['2.1.05','Sueldos por pagar','pasivo'],['2.1.06','AFP laboral por pagar','pasivo'],['2.1.07','RC-IVA retenido por pagar','pasivo'],['2.1.08','Aportes patronales por pagar','pasivo'],['2.1.09','Dividendos por pagar','pasivo'],['2.1.10','Provisión aguinaldo','pasivo'],['2.1.11','Provisión indemnización','pasivo'],['3.1.01','Capital social','patrimonio'],['3.1.02','Reserva legal','patrimonio'],['3.1.03','Resultados acumulados','patrimonio'],['3.1.04','Resultado de la gestión','patrimonio'],['4.1.01','Ventas','ingreso'],['5.1.01','Costo de ventas','gasto'],['5.2.01','Gasto alquiler','gasto'],['5.2.02','Gasto útiles de escritorio','gasto'],['5.2.03','Sueldos y salarios','gasto'],['5.2.04','Aportes patronales AFP','gasto'],['5.2.05','Aportes patronales CNS','gasto'],['5.2.06','Gasto aguinaldo','gasto'],['5.2.07','Gasto indemnización','gasto'],['5.2.08','Gasto IT','gasto'],['5.2.09','Gasto IUE','gasto']];
const seedParams=[['iva',13,'Porcentaje','editable'],['it',3,'Porcentaje','editable'],['iue',25,'Porcentaje','editable'],['afp_laboral',12.71,'Porcentaje','confirmar'],['afp_patronal',6.71,'Porcentaje','confirmar'],['cns_patronal',10,'Porcentaje','confirmar'],['prov_aguinaldo',1/12*100,'Porcentaje','confirmar'],['prov_indemnizacion',1/12*100,'Porcentaje','confirmar'],['reserva_legal',5,'Porcentaje','confirmar'],['salario_minimo',3300,'Bs','confirmar'],['min_no_imponible_rciva',13200,'Bs','confirmar']];
const months=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>(Number(n||0)/100).toLocaleString('es-BO',{minimumFractionDigits:2,maximumFractionDigits:2});const cents=v=>{let n=Number(String(v??'0').trim().replace(',','.'));return Number.isFinite(n)?Math.round((n+Number.EPSILON)*100):NaN};const val=(selector)=>$(selector)?.value?.trim()||'';const today=()=>{let d=new Date;return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};const fmtDate=s=>s?`${s.slice(8,10)}/${s.slice(5,7)}/${s.slice(0,4)}`:'';const monthName=(y,m)=>`${months[m-1]} ${y}`;
function fresh(){return{company:{name:'Empresa Comercial de Ejemplo',nit:'',address:'Bolivia'},accounts:seed.map((x,i)=>({id:i+1,code:x[0],name:x[1],type:x[2],accept:true})),periods:[{year:2026,month:11,status:'abierto'}],vouchers:[],invoices:[],thirdParties:[],employees:[],payrolls:[],retentions:[],parameters:Object.fromEntries(seedParams.map(x=>[x[0],{value:x[1],effective:'2026-01-01'}])),users:[{username:'admin',name:'Administrador',role:'admin',password:'admin123',active:true},{username:'contador',name:'Contador',role:'contador',password:'conta123',active:true},{username:'consulta',name:'Consulta',role:'consulta',password:'consulta123',active:true}],log:[],seq:seed.length+1}}
let db;try{db=JSON.parse(localStorage.getItem(KEY)||'null')}catch{db=null}if(!db||!db.accounts)db=fresh();
const cloudCfg=window.CONTADEMO_SUPABASE||{},cloudConfigured=Boolean(cloudCfg.url?.startsWith('https://')&&cloudCfg.publishableKey&&!cloudCfg.publishableKey.includes('PEGA_AQUI'));
let cloud=null,cloudReady=false,cloudRevision=0,pushTimer=0,pushing=false,loadingCloud=false,realtimeChannel=null;
function cleanPayload(){let copy=JSON.parse(JSON.stringify(db));delete copy.users;return copy}
function save(){localStorage.setItem(KEY,JSON.stringify(db));if(cloudReady&&activeUser?.role!=='consulta'&&!loadingCloud){clearTimeout(pushTimer);pushTimer=setTimeout(pushShared,650)}}save();let activeUser=null;
function toast(m,ok=false){let t=$('#toast');t.textContent=m;t.className='flash '+(ok?'ok':'');setTimeout(()=>{t.className='';t.textContent=''},3500)}
function setSync(text,ok=false){let el=$('#sync-status');if(el){el.textContent=text;el.style.color=ok?'#176b63':'#9a6530'}}
function normalizePayload(p){let base=fresh();return Object.assign(base,p,{users:base.users,log:Array.isArray(p.log)?p.log:[],accounts:Array.isArray(p.accounts)?p.accounts:base.accounts,periods:Array.isArray(p.periods)?p.periods:base.periods,vouchers:Array.isArray(p.vouchers)?p.vouchers:[],invoices:Array.isArray(p.invoices)?p.invoices:[],employees:Array.isArray(p.employees)?p.employees:[],payrolls:Array.isArray(p.payrolls)?p.payrolls:[],retentions:Array.isArray(p.retentions)?p.retentions:[],parameters:p.parameters||base.parameters})}
function acceptRemote(row,notify=false){if(!row)return;loadingCloud=true;db=normalizePayload(row.payload);cloudRevision=row.revision;localStorage.setItem(KEY,JSON.stringify(db));loadingCloud=false;if(notify&&activeUser){render();toast('Cambios del otro usuario recibidos.',true)}setSync('Sincronizado',true)}
async function profileFor(user){let {data,error}=await cloud.from('profiles').select('display_name,role,enabled').eq('user_id',user.id).maybeSingle();if(error)throw error;if(!data||!data.enabled)throw Error('Tu usuario no tiene un perfil activo. Pide al administrador que lo agregue en Supabase.');return data}
async function connectShared(user,profile){cloud=cloud||window.supabase.createClient(cloudCfg.url,cloudCfg.publishableKey);activeUser={username:user.email,name:profile.display_name||user.email,role:profile.role,uid:user.id};$('#login').classList.add('hidden');$('#app').classList.remove('hidden');navInit();setSync('Conectando…');let {data:row,error}=await cloud.from('company_state').select('id,payload,revision').eq('id',1).maybeSingle();if(error)throw error;if(!row){if(profile.role!=='admin')throw Error('El administrador debe ingresar primero para crear el espacio compartido.');let initial=cleanPayload();let ins=await cloud.from('company_state').insert({id:1,payload:initial}).select('id,payload,revision').single();if(ins.error)throw ins.error;row=ins.data}acceptRemote(row);cloudReady=true;subscribeShared();log('Inicio de sesión','Usuario',0,user.email);showPage(profile.role==='consulta'?'informes':'inicio')}
function subscribeShared(){if(!cloud||!activeUser)return;if(realtimeChannel)cloud.removeChannel(realtimeChannel);realtimeChannel=cloud.channel('contademo-shared-state').on('postgres_changes',{event:'UPDATE',schema:'public',table:'company_state',filter:'id=eq.1'},payload=>{if(pushing)return;if(payload.new.revision>cloudRevision){if(pushTimer){setSync('Hay cambios simultáneos');return}acceptRemote(payload.new,true)}}).subscribe(status=>{if(status==='SUBSCRIBED')setSync('En línea · sincronización automática',true);else if(status==='CHANNEL_ERROR')setSync('Sin conexión en tiempo real')})}
async function pushShared(){pushTimer=0;if(!cloudReady||!cloud||activeUser?.role==='consulta'||pushing)return;let snapshot=cleanPayload();pushing=true;setSync('Guardando…');try{let {data,error}=await cloud.from('company_state').update({payload:snapshot}).eq('id',1).eq('revision',cloudRevision).select('revision').maybeSingle();if(error)throw error;if(!data){download(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}),'copia-local-antes-de-sincronizar.json');let latest=await cloud.from('company_state').select('id,payload,revision').eq('id',1).single();if(latest.error)throw latest.error;acceptRemote(latest.data);toast('Otra persona guardó antes. Cargué la versión compartida y descargué una copia de tus cambios para recuperarlos.');return}cloudRevision=data.revision;localStorage.setItem(KEY,JSON.stringify(db));setSync('En línea · sincronizado',true)}catch(e){setSync('Pendiente de sincronización');toast(`No se pudo sincronizar: ${e.message}`)}finally{pushing=false}}
async function startCloudSession(user){try{cloud=window.supabase.createClient(cloudCfg.url,cloudCfg.publishableKey);let profile=await profileFor(user);await connectShared(user,profile)}catch(e){$('#login-error').textContent=e.message;setSync('Sin conectar');if(cloud)await cloud.auth.signOut()}}
window.addEventListener('online',()=>{if(cloudReady)pushShared()});
function log(action,entity,id,detail=''){db.log.unshift({id:db.log.length+1,user:activeUser?.username||'sistema',action,entity,entityId:id,date:new Date().toISOString(),detail});save()}
function account(code){return db.accounts.find(a=>a.code===code)}function accountById(id){return db.accounts.find(a=>a.id===Number(id))}function acctOptions(selected=''){return db.accounts.filter(a=>a.accept).map(a=>`<option value="${a.id}" ${a.id===Number(selected)?'selected':''}>${esc(a.code)} · ${esc(a.name)}</option>`).join('')}
function periodFor(date){return db.periods.find(p=>p.year===Number(date.slice(0,4))&&p.month===Number(date.slice(5,7)))}function periodOpen(date){let p=periodFor(date);return p&&p.status==='abierto'}function nextNumber(date){let y=date.slice(0,4);return db.vouchers.filter(v=>v.date.startsWith(y)).length+1}
function mkVoucher({date,type,glosa,lines,origin=''}){if(!periodOpen(date))throw Error(periodFor(date)?'El periodo está cerrado.':'Primero crea el periodo correspondiente.');let d=0,h=0;for(let l of lines){if(!accountById(l.accountId))throw Error('Selecciona una cuenta válida.');if(l.debit<0||l.credit<0||(l.debit===0&&l.credit===0)||(l.debit>0&&l.credit>0))throw Error('Cada línea debe llevar un importe positivo en Debe o en Haber, pero no en ambos.');d+=l.debit;h+=l.credit}if(d===0||d!==h)throw Error('El comprobante no cuadra: Debe y Haber deben coincidir.');let v={id:db.seq++,number:nextNumber(date),date,type,glosa,lines,status:'vigente',origin,user:activeUser.username,created:new Date().toISOString()};db.vouchers.push(v);log('Crear','Comprobante',v.id,`${v.number}: ${glosa}`);return v}
function reverseVoucher(id){let v=db.vouchers.find(x=>x.id===Number(id));if(!v||v.status!=='vigente')return toast('Ese comprobante ya no está vigente.');let d=v.lines.map(l=>({accountId:l.accountId,debit:l.credit,credit:l.debit,note:`Reversa: ${l.note||''}`}));try{let r=mkVoucher({date:today(),type:'traspaso',glosa:`Reversa del comprobante ${v.number}: ${v.glosa}`,lines:d,origin:`reversa:${v.id}`});v.status='anulado';v.reversedBy=r.id;save();log('Anular con reversa','Comprobante',v.id,`Reversa ${r.number}`);toast('Comprobante anulado mediante reversa.',true);render()}catch(e){toast(e.message)}}
function navInit(){let permitted=NAV.filter(([k])=>(activeUser?.role!=='consulta'||k==='informes')&&(activeUser?.role==='admin'||k!=='usuarios'));$('#nav').innerHTML=permitted.map(([k,n])=>`<button data-page="${k}">${n}</button>`).join('');$('#who').textContent=`${activeUser.name} · ${activeUser.role}`;$('#company-name').textContent=db.company.name;$('#nav').onclick=e=>{let b=e.target.closest('[data-page]');if(b)showPage(b.dataset.page)};}
function showPage(k){if(activeUser?.role==='consulta'&&k!=='informes')k='informes';$$nav().forEach(b=>b.classList.toggle('active',b.dataset.page===k));page=k;render()};let page='inicio';function $$nav(){return [...document.querySelectorAll('#nav button')]}function render(){if(!activeUser)return;$('#content').innerHTML=pages[page]?.()||pages.inicio();bindPage(page)}
const pages={
inicio(){let assets=trial().filter(x=>x.account.type==='activo').reduce((s,x)=>s+x.balance,0);return `<div class="title-row"><div><h1>Resumen contable</h1><p class="muted">${esc(db.company.name)} · ${esc(db.company.address)}</p></div><button data-action="new-voucher">＋ Comprobante</button></div><div class="cards"><div class="card accent"><span>Total activos registrados</span><strong>Bs ${money(assets)}</strong></div><div class="card"><span>Comprobantes vigentes</span><strong>${db.vouchers.filter(v=>v.status==='vigente').length}</strong></div><div class="card"><span>Facturas registradas</span><strong>${db.invoices.length}</strong></div><div class="card"><span>Periodo abierto</span><strong>${db.periods.filter(p=>p.status==='abierto').length}</strong></div></div><div class="panel"><h2>Accesos rápidos</h2><div class="actions"><button data-goto="comprobantes">Comprobantes</button><button data-goto="compras">Registrar compra</button><button data-goto="ventas">Registrar venta</button><button data-goto="informes">Ver estados</button></div></div><div class="panel"><h2>Movimientos recientes</h2>${voucherTable(db.vouchers.slice().sort((a,b)=>b.date.localeCompare(a.date)||b.number-a.number).slice(0,8))}</div>`},
 nuevo(){return `<div class="title-row"><div><h1>Nuevo comprobante</h1><p class="muted">El sistema solo guarda el asiento cuando Debe = Haber.</p></div></div><form id="manual-voucher" class="panel"><div class="fields"><label>Fecha<input name="date" type="date" value="${today()}" required></label><label>Tipo<select name="type"><option>apertura</option><option>ingreso</option><option>egreso</option><option>traspaso</option></select></label><label class="wide">Glosa<input name="glosa" maxlength="250" required></label></div><div class="title-row" style="margin-top:18px"><h2>Detalle</h2><button type="button" id="manual-add" class="light">＋ Agregar línea</button></div><div class="table-wrap"><table><thead><tr><th>Cuenta</th><th>Detalle</th><th class="num">Debe (Bs)</th><th class="num">Haber (Bs)</th><th></th></tr></thead><tbody id="manual-lines"></tbody></table></div><div class="totals"><span>Debe: <b id="manual-debit">0,00</b></span><span>Haber: <b id="manual-credit">0,00</b></span><b id="manual-status" class="error">No cuadra</b></div><button id="manual-save" disabled>Guardar comprobante</button></form>`},
cuentas(){return `<div class="title-row"><div><h1>Plan de cuentas</h1><p class="muted">Catálogo contable editable para esta empresa.</p></div><button data-action="add-account">＋ Agregar cuenta</button></div><div class="panel table-wrap"><table><thead><tr><th>Código</th><th>Nombre</th><th>Tipo</th><th>Movimiento</th><th></th></tr></thead><tbody>${db.accounts.map(a=>`<tr><td>${esc(a.code)}</td><td>${esc(a.name)}</td><td>${a.type}</td><td>${a.accept?'Sí':'No'}</td><td>${a.id>seed.length?`<button class="light" data-delete-account="${a.id}">Desactivar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`},
periodos(){return `<div class="title-row"><div><h1>Periodos contables</h1><p class="muted">No se admiten asientos en periodos cerrados.</p></div></div><form id="period-form" class="panel inline"><label>Año<input name="year" type="number" min="2000" max="2100" value="${new Date().getFullYear()}" required></label><label>Mes<select name="month">${months.map((x,i)=>`<option value="${i+1}">${x}</option>`).join('')}</select></label><button>Crear periodo</button></form><div class="panel table-wrap"><table><thead><tr><th>Periodo</th><th>Estado</th><th></th></tr></thead><tbody>${db.periods.slice().sort((a,b)=>b.year-a.year||b.month-a.month).map(p=>`<tr><td>${monthName(p.year,p.month)}</td><td><span class="pill ${p.status==='abierto'?'open':'closed'}">${p.status}</span></td><td><button class="light" data-period="${p.year}-${p.month}">${p.status==='abierto'?'Cerrar':'Abrir'}</button></td></tr>`).join('')}</tbody></table></div>`},
comprobantes(){return `<div class="title-row"><div><h1>Comprobantes</h1><p class="muted">Registro manual, correlativo por gestión y reversa de anulaciones.</p></div><button data-action="new-voucher">＋ Nuevo comprobante</button></div><div class="panel inline"><label>Buscar<input id="voucher-search" placeholder="Glosa"></label><label>Desde<input id="v-from" type="date"></label><label>Hasta<input id="v-to" type="date"></label></div><div id="voucher-list" class="panel table-wrap">${voucherTable(db.vouchers.slice().sort((a,b)=>b.date.localeCompare(a.date)||b.number-a.number),true)}</div>`},
compras(){return `<div class="title-row"><div><h1>Registro de compras</h1><p class="muted">Facturas registradas manualmente con cálculo demostrativo de Crédito Fiscal IVA.</p></div></div>${invoiceForm('compra')}<div class="panel table-wrap"><h2>Compras registradas</h2>${invoiceTable('compra')}</div>`},
ventas(){return `<div class="title-row"><div><h1>Registro de ventas</h1><p class="muted">Facturas registradas manualmente con cálculo demostrativo de Débito Fiscal IVA.</p></div></div>${invoiceForm('venta')}<div class="panel table-wrap"><h2>Ventas registradas</h2>${invoiceTable('venta')}</div>`},
retenciones(){return `<div class="title-row"><div><h1>Libro de Retenciones</h1><p class="muted">Registro manual de retenciones para fines académicos.</p></div></div><form id="ret-form" class="panel fields"><label>Fecha<input name="date" type="date" value="${today()}" required></label><label>Tercero<input name="third" required></label><label>NIT / CI<input name="nit"></label><label>Tipo<select name="type"><option>RC-IVA</option><option>IT</option><option>IUE</option><option>Otro</option></select></label><label>Documento<input name="doc"></label><label>Importe retenido (Bs)<input name="amount" type="number" min="0.01" step="0.01" required></label><label class="wide">Observación<input name="note"></label><button>Guardar retención</button></form><div class="panel table-wrap"><table><thead><tr><th>Fecha</th><th>Tercero</th><th>NIT / CI</th><th>Tipo</th><th>Documento</th><th class="num">Importe</th><th>Observación</th></tr></thead><tbody>${db.retentions.map(r=>`<tr><td>${fmtDate(r.date)}</td><td>${esc(r.third)}</td><td>${esc(r.nit)}</td><td>${r.type}</td><td>${esc(r.doc)}</td><td class="num">${money(r.amount)}</td><td>${esc(r.note)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Sin retenciones registradas.</td></tr>'}</tbody></table></div>`},
personal(){return `<div class="title-row"><div><h1>Personal y planillas</h1><p class="muted">Personal, cálculo de aportes y provisiones; reglas y tasas editables.</p></div></div><div class="grid2"><form id="employee-form" class="panel fields"><h2 class="wide">Registrar empleado</h2><label>Nombre<input name="name" required></label><label>Cargo<input name="role"></label><label>Haber básico (Bs)<input name="salary" type="number" min="0" step="0.01" required></label><label>Fecha de ingreso<input name="date" type="date" value="${today()}"></label><label>Bono antigüedad mensual (Bs)<input name="seniority" type="number" min="0" step="0.01" value="0"></label><button>Guardar empleado</button></form><form id="payroll-form" class="panel fields"><h2 class="wide">Crear planilla</h2><label>Año<input name="year" type="number" value="${new Date().getFullYear()}"></label><label>Mes<select name="month">${months.map((x,i)=>`<option value="${i+1}">${x}</option>`).join('')}</select></label><button class="wide">Calcular planilla</button><small class="wide muted">Calcula haberes, AFP laboral, AFP/CNS patronales, aguinaldo e indemnización. RC-IVA se edita a mano.</small></form></div><div class="panel"><h2>Empleados</h2>${employeeTable()}</div><div class="panel"><h2>Planillas</h2>${payrollTable()}</div>`},
parametros(){return `<div class="title-row"><div><h1>Parámetros tributarios y laborales</h1><p class="muted">Se pueden editar y llevan fecha de vigencia.</p></div></div><div class="notice">Verifica las tasas y reglas en fuentes oficiales antes de utilizarlas. Este prototipo no prepara declaraciones oficiales.</div><form id="params-form" class="panel table-wrap"><table><thead><tr><th>Parámetro</th><th>Valor</th><th>Unidad</th><th>Vigente desde</th><th>Nota</th></tr></thead><tbody>${seedParams.map(([k,,unit,note])=>{let value=Number(db.parameters[k]?.value??0);return `<tr><td>${k.replaceAll('_',' ')}</td><td><input name="${k}" type="number" step="0.0001" value="${value.toFixed(4)}"></td><td>${unit}</td><td><input name="${k}_date" type="date" value="${db.parameters[k]?.effective||'2026-01-01'}"></td><td>${note==='confirmar'?'<span class="error">Verifique estas tasas en fuentes oficiales.</span>':''}</td></tr>`}).join('')}</tbody></table><button>Guardar parámetros</button></form>`},
usuarios(){if(cloudConfigured)return `<div class="title-row"><div><h1>Usuarios y roles</h1><p class="muted">Cuentas del espacio compartido.</p></div></div><div class="panel"><h2>Administrar accesos desde Supabase</h2><ol><li>En el panel de Supabase, abre Authentication → Users y crea el usuario.</li><li>Ejecuta en SQL Editor el alta en <code>public.profiles</code> usando su ID, con rol <code>admin</code>, <code>contador</code> o <code>consulta</code>.</li><li>La próxima vez que inicie sesión, verá la empresa compartida. El rol Consulta solo puede ver informes.</li></ol><p class="notice">El proyecto no permite registros públicos. Solo podrán entrar los usuarios que el administrador agregue en Supabase.</p></div>`;return `<div class="title-row"><div><h1>Usuarios y roles</h1><p class="muted">Cuentas locales de demostración del sistema.</p></div></div><div class="notice">Las cuentas solo protegen la vista de esta demostración local; no se deben usar contraseñas reales.</div><form id="user-form" class="panel fields"><label>Usuario<input name="username" required></label><label>Nombre<input name="name" required></label><label>Contraseña inicial<input name="password" required></label><label>Rol<select name="role"><option value="contador">Contador</option><option value="consulta">Consulta</option><option value="admin">Administrador</option></select></label><button>Crear usuario</button></form><div class="panel table-wrap"><table><thead><tr><th>Usuario</th><th>Nombre</th><th>Rol</th><th>Estado</th></tr></thead><tbody>${db.users.map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(u.name)}</td><td>${u.role}</td><td>${u.active?'Activo':'Inactivo'}</td></tr>`).join('')}</tbody></table></div>`},
bitacora(){return `<div class="title-row"><div><h1>Bitácora</h1><p class="muted">Registro de acciones realizadas en el prototipo.</p></div></div><div class="panel table-wrap"><table><thead><tr><th>Fecha y hora</th><th>Usuario</th><th>Acción</th><th>Entidad</th><th>Detalle</th></tr></thead><tbody>${db.log.map(l=>`<tr><td>${new Date(l.date).toLocaleString('es-BO')}</td><td>${esc(l.user)}</td><td>${esc(l.action)}</td><td>${esc(l.entity)}</td><td>${esc(l.detail)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">La bitácora aparecerá al registrar operaciones.</td></tr>'}</tbody></table></div>`},
informes(){return `<div class="title-row"><div><h1>Informes</h1><p class="muted">Diario, mayor, sumas y saldos, estados financieros e informes de impuestos demostrativos.</p></div><div class="actions"><button id="print-report" class="light">Imprimir / PDF</button><button id="csv-report" class="light">Exportar CSV</button></div></div><form id="report-form" class="panel inline"><label>Gestión<input name="year" type="number" value="${new Date().getFullYear()}"></label><label>Mes<select name="month"><option value="0">Año completo</option>${months.map((x,i)=>`<option value="${i+1}">${x}</option>`).join('')}</select></label><label>Informe<select name="type"><option value="todos">Todos los estados</option><option value="diario">Libro Diario</option><option value="mayor">Libro Mayor</option><option value="trial">Sumas y Saldos</option><option value="income">Estado de Resultados</option><option value="balance">Balance General</option><option value="cash">Flujo de Efectivo</option><option value="equity">Evolución del Patrimonio</option><option value="compras">Registro de Compras</option><option value="ventas">Registro de Ventas</option><option value="tax">Resumen IVA e IT</option><option value="ret">Libro de Retenciones</option></select></label><button>Generar</button></form><div id="report-result"></div>`}
};
function voucherTable(list,buttons=false){return `<table><thead><tr><th>Fecha</th><th>N.º</th><th>Tipo</th><th>Glosa</th><th class="num">Debe</th><th class="num">Haber</th><th>Estado</th>${buttons?'<th>Acción</th>':''}</tr></thead><tbody>${list.length?list.map(v=>`<tr><td>${fmtDate(v.date)}</td><td>${v.number}</td><td>${v.type}</td><td>${esc(v.glosa)}</td><td class="num">${money(v.lines.reduce((a,l)=>a+l.debit,0))}</td><td class="num">${money(v.lines.reduce((a,l)=>a+l.credit,0))}</td><td>${v.status}</td>${buttons?`<td>${v.status==='vigente'?`<button class="light" data-reverse="${v.id}">Anular</button>`:''}</td>`:''}</tr>`).join(''):'<tr><td colspan="8" class="empty">Sin comprobantes.</td></tr>'}</tbody></table>`}
function invoiceForm(kind){let isBuy=kind==='compra',pref=isBuy?'Compra':'Venta';return `<form id="invoice-form" data-kind="${kind}" class="panel fields"><h2 class="wide">Registrar factura de ${kind}</h2><label>Fecha<input name="date" type="date" value="${today()}" required></label><label>NIT del tercero<input name="nit" required></label><label>Razón social<input name="third" required></label><label>N.º factura<input name="number" required></label><label>Código de autorización / CUF<input name="auth"></label><label>Importe total (Bs)<input name="total" type="number" min="0.01" step="0.01" required></label><label class="wide">Cuenta de ${isBuy?'gasto o activo':'cobro'}<select name="main">${acctOptions(account(isBuy?'1.1.04':'1.1.02')?.id)}</select></label><label>Contrapartida<select name="other">${acctOptions(account(isBuy?'2.1.01':'1.1.03')?.id)}</select></label><label class="wide"><span><input name="journal" type="checkbox" checked style="width:auto"> Generar comprobante contable automático</span></label><p class="wide muted">El IVA se calcula como tasa incluida en el total: ${Number(db.parameters.iva?.value??13)}% del total. Revisa la tasa en Parámetros.</p><button>${pref}: guardar</button></form>`}
function invoiceTable(kind){let list=db.invoices.filter(x=>x.kind===kind);return `<table><thead><tr><th>Fecha</th><th>Tercero / NIT</th><th>N.º factura</th><th class="num">Total</th><th class="num">IVA</th><th>Comprobante</th></tr></thead><tbody>${list.length?list.map(i=>`<tr><td>${fmtDate(i.date)}</td><td>${esc(i.third)} / ${esc(i.nit)}</td><td>${esc(i.number)}</td><td class="num">${money(i.total)}</td><td class="num">${money(i.vat)}</td><td>${i.voucherId?`#${db.vouchers.find(v=>v.id===i.voucherId)?.number||''}`:'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No hay facturas registradas.</td></tr>'}</tbody></table>`}
function employeeTable(){return `<div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Cargo</th><th class="num">Haber básico</th><th class="num">Antigüedad</th><th>Ingreso</th></tr></thead><tbody>${db.employees.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.role)}</td><td class="num">${money(e.salary)}</td><td class="num">${money(e.seniority)}</td><td>${fmtDate(e.date)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Agrega empleados para calcular planillas.</td></tr>'}</tbody></table></div>`}
function payrollTable(){return `<div class="table-wrap"><table><thead><tr><th>Periodo</th><th>Empleados</th><th>Estado</th><th class="num">Total ganado</th><th class="num">Líquido</th><th></th></tr></thead><tbody>${db.payrolls.map(p=>`<tr><td>${monthName(p.year,p.month)}</td><td>${p.lines.length}</td><td>${p.status}</td><td class="num">${money(p.lines.reduce((a,l)=>a+l.gross,0))}</td><td class="num">${money(p.lines.reduce((a,l)=>a+l.net,0))}</td><td>${p.status!=='contabilizada'?`<button data-payroll="${p.id}">Editar / contabilizar</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Sin planillas.</td></tr>'}</tbody></table></div>`}
function booked(v){return v.status==='vigente'||Boolean(v.reversedBy)}function trial(year=null){let rows=db.accounts.map(a=>({account:a,debit:0,credit:0,balance:0}));let map=new Map(rows.map(r=>[r.account.id,r]));db.vouchers.filter(v=>booked(v)&&(!year||v.date.startsWith(String(year)))).forEach(v=>v.lines.forEach(l=>{let r=map.get(l.accountId);if(r){r.debit+=l.debit;r.credit+=l.credit}}));rows.forEach(r=>r.balance=r.debit-r.credit);return rows}
function bindPage(k){let c=$('#content');c.onclick=e=>{let a=e.target.closest('[data-action]')?.dataset.action;if(a==='new-voucher')showPage('nuevo');if(a==='add-account')addAccount();let goto=e.target.closest('[data-goto]')?.dataset.goto;if(goto)showPage(goto);let period=e.target.closest('[data-period]')?.dataset.period;if(period){let[y,m]=period.split('-').map(Number),p=db.periods.find(x=>x.year===y&&x.month===m);p.status=p.status==='abierto'?'cerrado':'abierto';save();render()}let rev=e.target.closest('[data-reverse]')?.dataset.reverse;if(rev)reverseVoucher(rev);let del=e.target.closest('[data-delete-account]')?.dataset.deleteAccount;if(del){let acc=accountById(del);acc.accept=false;save();render()}let payroll=e.target.closest('[data-payroll]')?.dataset.payroll;if(payroll)editPayroll(Number(payroll));if(e.target.closest('[data-post-it]')){let f=new FormData($('#report-form'));postIT(Number(f.get('year')),Number(f.get('month')))}if(e.target.closest('[data-close-year]')){let f=new FormData($('#report-form'));closeYear(Number(f.get('year')))}};
if(k==='nuevo'){let tbody=$('#manual-lines');function addManual(){let tr=document.createElement('tr');tr.innerHTML=`<td><select class="manual-account" required><option value="">Selecciona</option>${db.accounts.filter(a=>a.accept).map(a=>`<option value="${a.id}">${esc(a.code)} · ${esc(a.name)}</option>`).join('')}</select></td><td><input class="manual-note" placeholder="Detalle"></td><td><input class="manual-d" type="number" min="0" step="0.01" value="0.00"></td><td><input class="manual-c" type="number" min="0" step="0.01" value="0.00"></td><td><button type="button" class="light remove-manual">Quitar</button></td>`;tbody.append(tr);tr.addEventListener('input',calc);tr.addEventListener('change',calc);tr.querySelector('.remove-manual').onclick=()=>{tr.remove();calc()}}function calc(){let d=0,h=0,ok=true;[...tbody.rows].forEach(tr=>{let a=cents(tr.querySelector('.manual-d').value),b=cents(tr.querySelector('.manual-c').value);d+=a||0;h+=b||0;if(!tr.querySelector('.manual-account').value||!Number.isFinite(a)||!Number.isFinite(b)||(!a&&!b)||(a&&b))ok=false});$('#manual-debit').textContent=money(d);$('#manual-credit').textContent=money(h);ok=ok&&d>0&&d===h;$('#manual-status').textContent=ok?'Cuadra':'No cuadra';$('#manual-status').className=ok?'good':'error';$('#manual-save').disabled=!ok;return ok}$('#manual-lines').innerHTML='';addManual();addManual();$('#manual-add').onclick=addManual;$('#manual-lines').addEventListener('click',e=>{if(e.target.matches('.remove-manual')){e.target.closest('tr').remove();calc()}});$('#manual-voucher').onsubmit=e=>{e.preventDefault();if(!calc())return;let f=new FormData(e.target);try{let lines=[...tbody.rows].map(tr=>({accountId:Number(tr.querySelector('.manual-account').value),debit:cents(tr.querySelector('.manual-d').value),credit:cents(tr.querySelector('.manual-c').value),note:tr.querySelector('.manual-note').value.trim()}));mkVoucher({date:f.get('date'),type:f.get('type'),glosa:f.get('glosa').trim(),lines});save();toast('Comprobante guardado y cuadrado.',true);showPage('comprobantes')}catch(err){toast(err.message)}}}
if(k==='periodos')$('#period-form').onsubmit=e=>{e.preventDefault();let y=Number(e.target.year.value),m=Number(e.target.month.value);if(db.periods.some(p=>p.year===y&&p.month===m))return toast('El periodo ya existe.');db.periods.push({year:y,month:m,status:'abierto'});save();log('Crear','Periodo',0,monthName(y,m));render()};
if(k==='comprobantes'){let f=()=>{let q=val('#voucher-search').toLowerCase(),from=val('#v-from'),to=val('#v-to');let l=db.vouchers.filter(v=>(!q||v.glosa.toLowerCase().includes(q))&&(!from||v.date>=from)&&(!to||v.date<=to)).sort((a,b)=>b.date.localeCompare(a.date)||b.number-a.number);$('#voucher-list').innerHTML=voucherTable(l,true)};['#voucher-search','#v-from','#v-to'].forEach(s=>$(s).oninput=f)}
if(k==='compras'||k==='ventas'){$('#invoice-form').onsubmit=e=>{e.preventDefault();saveInvoice(e.target)};}
if(k==='retenciones')$('#ret-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),amount=cents(f.get('amount'));if(!periodOpen(f.get('date')))return toast('Crea o abre el periodo de la retención.');db.retentions.unshift({id:db.seq++,date:f.get('date'),third:f.get('third'),nit:f.get('nit'),type:f.get('type'),doc:f.get('doc'),amount,note:f.get('note')});save();log('Registrar','Retención',db.seq-1,f.get('type'));render()};
if(k==='personal'){ $('#employee-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);db.employees.push({id:db.seq++,name:f.get('name'),role:f.get('role'),salary:cents(f.get('salary')),date:f.get('date'),seniority:cents(f.get('seniority'))});save();log('Crear','Empleado',db.seq-1,f.get('name'));render()};$('#payroll-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),y=Number(f.get('year')),m=Number(f.get('month'));if(db.payrolls.some(p=>p.year===y&&p.month===m))return toast('Ya existe planilla para ese mes.');let lines=db.employees.map(emp=>payLine(emp,30,0,0,0,0));let p={id:db.seq++,year:y,month:m,status:'calculada',lines,voucherId:null};db.payrolls.push(p);save();log('Calcular','Planilla',p.id,monthName(y,m));render();editPayroll(p.id)}}
if(k==='parametros')$('#params-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);seedParams.forEach(([key])=>db.parameters[key]={value:Number(f.get(key)),effective:f.get(`${key}_date`)});save();log('Editar','Parámetros',0,'Parámetros tributarios/laborales');toast('Parámetros guardados.',true);render()};
if(k==='usuarios')$('#user-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),username=f.get('username').trim();if(db.users.some(u=>u.username===username))return toast('Ese usuario ya existe.');db.users.push({username,name:f.get('name'),role:f.get('role'),password:f.get('password'),active:true});save();log('Crear','Usuario',0,username);render()};
if(k==='informes'){let f=$('#report-form');f.onsubmit=e=>{e.preventDefault();makeReport(new FormData(f))};$('#print-report').onclick=()=>print();$('#csv-report').onclick=()=>csvReport();}}
function saveInvoice(form){let f=new FormData(form),kind=form.dataset.kind,date=f.get('date'),nit=f.get('nit').trim(),number=f.get('number').trim(),total=cents(f.get('total'));if(!Number.isFinite(total)||total<=0)return toast('Ingresa un total válido.');if(!periodOpen(date))return toast('Crea o abre el periodo de la factura.');if(db.invoices.some(i=>i.nit===nit&&i.number===number))return toast('Ya existe una factura con ese NIT y número.');let rate=Number(db.parameters.iva.value)/100,vat=Math.round(total*rate),net=total-vat,voucher=null;try{if(f.get('journal')){let main=Number(f.get('main')),other=Number(f.get('other')),vatAcc=account(kind==='compra'?'1.1.05':'2.1.02'),sales=account('4.1.01');let lines=kind==='compra'?[{accountId:main,debit:net,credit:0,note:'Compra neta'},{accountId:vatAcc.id,debit:vat,credit:0,note:'Crédito fiscal IVA'},{accountId:other,debit:0,credit:total,note:'Proveedor / pago'}]:[{accountId:other,debit:total,credit:0,note:'Cobro / cliente'},{accountId:sales.id,debit:0,credit:net,note:'Venta neta'},{accountId:vatAcc.id,debit:0,credit:vat,note:'Débito fiscal IVA'}];voucher=mkVoucher({date,type:kind==='compra'?'egreso':'ingreso',glosa:`Factura ${kind} ${number} · ${f.get('third')}`,lines,origin:`factura-${kind}`})}let inv={id:db.seq++,kind,date,nit,third:f.get('third').trim(),number,auth:f.get('auth'),total,vat,net,voucherId:voucher?.id||null};db.invoices.push(inv);if(!db.thirdParties.some(t=>t.nit===nit))db.thirdParties.push({nit,name:inv.third,kind:kind==='compra'?'proveedor':'cliente'});save();log('Registrar factura',kind,inv.id,`${number} · ${money(total)} Bs`);toast('Factura registrada.',true);render()}catch(err){toast(err.message)}}
function param(k){return Number(db.parameters[k]?.value||0)}function pct(base,p){return Math.round(base*p/100)}
function payLine(emp,days,other,rciva,advance,deduct){let gross=Math.round(emp.salary*days/30)+emp.seniority+other,afp=pct(gross,param('afp_laboral')),net=gross-afp-rciva-advance-deduct;return{employeeId:emp.id,days,gross,afp,rciva,advance,deduct,net,patAfp:pct(gross,param('afp_patronal')),patCns:pct(gross,param('cns_patronal')),aguinaldo:pct(gross,param('prov_aguinaldo')),indemnizacion:pct(gross,param('prov_indemnizacion')),other}}
function editPayroll(id){let p=db.payrolls.find(x=>x.id===id);if(!p||p.status==='contabilizada')return;let body=p.lines.map((l,i)=>{let e=db.employees.find(x=>x.id===l.employeeId);return `<tr data-employee="${e.id}"><td>${esc(e.name)}</td><td><input class="days" type="number" min="0" max="30" value="${l.days}"></td><td><input class="other" type="number" step="0.01" value="${money(l.other)}"></td><td class="gross"></td><td class="afp"></td><td><input class="rciva" type="number" step="0.01" value="${money(l.rciva)}"></td><td><input class="advance" type="number" step="0.01" value="${money(l.advance)}"></td><td><input class="deduct" type="number" step="0.01" value="${money(l.deduct)}"></td><td class="net"></td></tr>`}).join('');let box=document.createElement('div');box.className='flash';box.style.cssText='inset:5vh 3vw auto;max-width:none;max-height:90vh;overflow:auto;background:white;color:var(--ink)';box.innerHTML=`<h2>Planilla · ${monthName(p.year,p.month)}</h2><div class="notice">Si el total ganado supera Bs ${money(param('min_no_imponible_rciva')*100)}, revisa RC-IVA manualmente.</div><div class="table-wrap"><table><thead><tr><th>Empleado</th><th>Días</th><th>Otros ingresos</th><th>Ganado</th><th>AFP laboral</th><th>RC-IVA</th><th>Anticipos</th><th>Otros desc.</th><th>Líquido</th></tr></thead><tbody>${body}</tbody></table></div><p id="payroll-totals"></p><div class="actions"><button id="save-payroll" class="light">Guardar cálculo</button><button id="post-payroll">Contabilizar planilla</button><button id="close-payroll" class="danger">Cerrar</button></div>`;document.body.append(box);function recalc(){let tot={gross:0,net:0,patAfp:0,patCns:0,prov:0};box.querySelectorAll('tbody tr').forEach(tr=>{let emp=db.employees.find(e=>e.id===Number(tr.dataset.employee)),l=payLine(emp,Number(tr.querySelector('.days').value),cents(tr.querySelector('.other').value),cents(tr.querySelector('.rciva').value),cents(tr.querySelector('.advance').value),cents(tr.querySelector('.deduct').value));tr.querySelector('.gross').textContent=money(l.gross);tr.querySelector('.afp').textContent=money(l.afp);tr.querySelector('.net').textContent=money(l.net);tot.gross+=l.gross;tot.net+=l.net;tot.patAfp+=l.patAfp;tot.patCns+=l.patCns;tot.prov+=l.aguinaldo+l.indemnizacion;tr.dataset.line=JSON.stringify(l)});box.querySelector('#payroll-totals').textContent=`Total ganado Bs ${money(tot.gross)} · Líquido Bs ${money(tot.net)} · Aportes patronales Bs ${money(tot.patAfp+tot.patCns)} · Provisiones Bs ${money(tot.prov)}`;return[...box.querySelectorAll('tbody tr')].map(tr=>JSON.parse(tr.dataset.line))}box.addEventListener('input',recalc);recalc();box.querySelector('#close-payroll').onclick=()=>box.remove();box.querySelector('#save-payroll').onclick=()=>{p.lines=recalc();save();toast('Cálculo guardado.',true);box.remove();render()};box.querySelector('#post-payroll').onclick=()=>{p.lines=recalc();try{let s={gross:0,afp:0,rciva:0,net:0,patAfp:0,patCns:0,aguinaldo:0,indemnizacion:0};p.lines.forEach(l=>Object.keys(s).forEach(k=>s[k]+=l[k]||0));let date=`${p.year}-${String(p.month).padStart(2,'0')}-28`;let lines=[['5.2.03',s.gross,'debe','Sueldos'],['5.2.04',s.patAfp,'debe','AFP patronal'],['5.2.05',s.patCns,'debe','CNS patronal'],['5.2.06',s.aguinaldo,'debe','Provisión aguinaldo'],['5.2.07',s.indemnizacion,'debe','Provisión indemnización'],['2.1.06',s.afp,'haber','AFP laboral por pagar'],['2.1.07',s.rciva,'haber','RC-IVA por pagar'],['2.1.05',s.net,'haber','Sueldos por pagar'],['2.1.08',s.patAfp+s.patCns,'haber','Aportes patronales por pagar'],['2.1.10',s.aguinaldo,'haber','Provisión aguinaldo'],['2.1.11',s.indemnizacion,'haber','Provisión indemnización']].filter(x=>x[1]>0).map(x=>({accountId:account(x[0]).id,debit:x[2]==='debe'?x[1]:0,credit:x[2]==='haber'?x[1]:0,note:x[3]}));let v=mkVoucher({date,type:'egreso',glosa:`Planilla ${monthName(p.year,p.month)}`,lines,origin:`planilla:${p.id}`});p.status='contabilizada';p.voucherId=v.id;save();log('Contabilizar','Planilla',p.id,monthName(p.year,p.month));toast('Planilla contabilizada.',true);box.remove();render()}catch(err){toast(err.message)}}}
function addAccount(){let code=prompt('Código de la cuenta (ej. 1.1.07):');if(!code)return;let name=prompt('Nombre de la cuenta:');if(!name)return;let type=prompt('Tipo: activo, pasivo, patrimonio, ingreso o gasto','activo');if(!['activo','pasivo','patrimonio','ingreso','gasto'].includes(type))return toast('Tipo de cuenta inválido.');if(db.accounts.some(a=>a.code===code))return toast('Ese código ya existe.');db.accounts.push({id:db.seq++,code,name,type,accept:true});save();log('Crear','Cuenta',db.seq-1,`${code} ${name}`);render()}

function makeReport(f){let y=Number(f.get('year')),m=Number(f.get('month')),type=f.get('type');let inPeriod=d=>Number(d.slice(0,4))===y&&(!m||Number(d.slice(5,7))===m);let vs=db.vouchers.filter(v=>booked(v)&&inPeriod(v.date)).sort((a,b)=>a.date.localeCompare(b.date)||a.number-b.number),invs=db.invoices.filter(i=>inPeriod(i.date));let sums=new Map(db.accounts.map(a=>[a.id,{debit:0,credit:0,moves:[]} ]));vs.forEach(v=>v.lines.forEach(l=>{let s=sums.get(l.accountId);if(s){s.debit+=l.debit;s.credit+=l.credit;s.moves.push({v,l})}}));let result=$('#report-result');let sections=[];const include=k=>type==='todos'||type===k;
if(include('diario'))sections.push(`<div class="panel"><h2>Libro Diario · ${m?monthName(y,m):y}</h2>${vs.map(v=>`<div class="journal"><b>${fmtDate(v.date)} · Comprobante ${v.number} · ${esc(v.glosa)}</b>${v.lines.map(l=>{let a=accountById(l.accountId);return `<div class="journal-line"><span>${esc(a?.code)} · ${esc(a?.name)}</span><span class="num">${l.debit?money(l.debit):''}</span><span class="num">${l.credit?money(l.credit):''}</span></div>`}).join('')}</div>`).join('')||'<div class="empty">Sin movimientos.</div>'}</div>`);
if(include('mayor'))sections.push(`<h2 class="report-title">Libro Mayor</h2>${db.accounts.filter(a=>sums.get(a.id).moves.length).map(a=>{let run=0;return `<div class="panel table-wrap"><h3>${a.code} · ${esc(a.name)}</h3><table><tr><th>Fecha</th><th>N.º</th><th>Glosa</th><th class="num">Debe</th><th class="num">Haber</th><th class="num">Saldo</th></tr>${sums.get(a.id).moves.map(({v,l})=>{run+=l.debit-l.credit;return `<tr><td>${fmtDate(v.date)}</td><td>${v.number}</td><td>${esc(v.glosa)}</td><td class="num">${l.debit?money(l.debit):''}</td><td class="num">${l.credit?money(l.credit):''}</td><td class="num">${money(Math.abs(run))} ${run>=0?'D':'A'}</td></tr>`}).join('')}</table></div>`}).join('')||'<div class="empty">Sin movimientos.</div>'}`);
if(include('trial')){let rows=[...sums].map(([id,s])=>({a:accountById(id),...s,sd:Math.max(0,s.debit-s.credit),sa:Math.max(0,s.credit-s.debit)})).filter(x=>x.debit||x.credit);let td=rows.reduce((a,r)=>a+r.debit,0),th=rows.reduce((a,r)=>a+r.credit,0);sections.push(`<div class="panel table-wrap"><h2>Balance de Sumas y Saldos</h2><table><tr><th>Cuenta</th><th class="num">Debe</th><th class="num">Haber</th><th class="num">Saldo deudor</th><th class="num">Saldo acreedor</th></tr>${rows.map(r=>`<tr><td>${r.a.code} · ${esc(r.a.name)}</td><td class="num">${money(r.debit)}</td><td class="num">${money(r.credit)}</td><td class="num">${money(r.sd)}</td><td class="num">${money(r.sa)}</td></tr>`).join('')}<tr class="total-row"><td>Totales · ${td===th?'Cuadra':'No cuadra'}</td><td class="num">${money(td)}</td><td class="num">${money(th)}</td><td class="num">${money(rows.reduce((a,r)=>a+r.sd,0))}</td><td class="num">${money(rows.reduce((a,r)=>a+r.sa,0))}</td></tr></table></div>`)}
let income=db.accounts.filter(a=>a.type==='ingreso').reduce((s,a)=>s+sums.get(a.id).credit-sums.get(a.id).debit,0),expenses=db.accounts.filter(a=>a.type==='gasto').reduce((s,a)=>s+sums.get(a.id).debit-sums.get(a.id).credit,0),profit=income-expenses;
if(include('income'))sections.push(`<div class="panel table-wrap"><h2>Estado de Resultados</h2><table><tr><th>Concepto</th><th class="num">Bs</th></tr>${db.accounts.filter(a=>a.type==='ingreso'&&sums.get(a.id).credit+sums.get(a.id).debit).map(a=>`<tr><td>${a.name}</td><td class="num">${money(sums.get(a.id).credit-sums.get(a.id).debit)}</td></tr>`).join('')}<tr class="total-row"><td>Total ingresos</td><td class="num">${money(income)}</td></tr>${db.accounts.filter(a=>a.type==='gasto'&&sums.get(a.id).credit+sums.get(a.id).debit).map(a=>`<tr><td>${a.name}</td><td class="num">${money(sums.get(a.id).debit-sums.get(a.id).credit)}</td></tr>`).join('')}<tr class="total-row"><td>Total gastos</td><td class="num">${money(expenses)}</td></tr><tr class="total-row"><td>Resultado del periodo</td><td class="num">${money(profit)}</td></tr></table></div>`);
if(include('balance')){let rows=db.accounts.filter(a=>['activo','pasivo','patrimonio'].includes(a.type)&&sums.get(a.id).debit+sums.get(a.id).credit);let subt={activo:0,pasivo:0,patrimonio:0};rows.forEach(a=>{let s=sums.get(a.id);subt[a.type]+=a.type==='activo'?s.debit-s.credit:s.credit-s.debit});subt.patrimonio+=profit;let totalPE=subt.pasivo+subt.patrimonio;sections.push(`<div class="panel table-wrap"><h2>Balance General</h2><table><tr><th>Grupo / cuenta</th><th class="num">Saldo (Bs)</th></tr>${rows.map(a=>{let s=sums.get(a.id);return `<tr><td>${a.type} · ${a.code} ${esc(a.name)}</td><td class="num">${money(a.type==='activo'?s.debit-s.credit:s.credit-s.debit)}</td></tr>`}).join('')}<tr class="total-row"><td>Total Activo</td><td class="num">${money(subt.activo)}</td></tr><tr class="total-row"><td>Total Pasivo</td><td class="num">${money(subt.pasivo)}</td></tr><tr class="total-row"><td>Patrimonio antes del resultado</td><td class="num">${money(subt.patrimonio-profit)}</td></tr><tr><td>Resultado del periodo</td><td class="num">${money(profit)}</td></tr><tr class="total-row"><td>Total Pasivo y Patrimonio</td><td class="num">${money(totalPE)}</td></tr><tr><td>Comprobación</td><td class="num">${Math.abs(subt.activo-totalPE)<0.01?'Cuadra':'Revisar saldos iniciales'}</td></tr></table></div>`)}
if(include('cash')){let cashIds=new Set(db.accounts.filter(a=>a.code.startsWith('1.1.01')||a.code.startsWith('1.1.02')).map(a=>a.id));let mov=vs.flatMap(v=>v.lines.filter(l=>cashIds.has(l.accountId)).map(l=>({v,l})));let ins=mov.reduce((s,x)=>s+x.l.debit,0),outs=mov.reduce((s,x)=>s+x.l.credit,0);sections.push(`<div class="panel"><h2>Flujo de Efectivo (movimientos de Caja y Banco)</h2><p>Entradas: <b>Bs ${money(ins)}</b> · Salidas: <b>Bs ${money(outs)}</b> · Variación: <b>Bs ${money(ins-outs)}</b></p><p class="muted">Este flujo resume los movimientos registrados en cuentas Caja y Banco del periodo.</p></div>`)}
if(include('equity')){let eq=db.accounts.filter(a=>a.type==='patrimonio');sections.push(`<div class="panel table-wrap"><h2>Evolución del Patrimonio (movimientos del periodo)</h2><table><tr><th>Cuenta patrimonial</th><th class="num">Saldo inicial del periodo*</th><th class="num">Aumentos</th><th class="num">Disminuciones</th><th class="num">Saldo neto</th></tr>${eq.map(a=>{let s=sums.get(a.id),increase=s.credit,decrease=s.debit;return `<tr><td>${a.code} · ${esc(a.name)}</td><td class="num">—</td><td class="num">${money(increase)}</td><td class="num">${money(decrease)}</td><td class="num">${money(increase-decrease)}</td></tr>`}).join('')}<tr><td>Resultado del periodo</td><td class="num">—</td><td class="num">${money(Math.max(0,profit))}</td><td class="num">${money(Math.max(0,-profit))}</td><td class="num">${money(profit)}</td></tr></table><small class="muted">*La versión académica muestra movimientos; saldos iniciales deben registrarse mediante comprobante de apertura.</small></div>`)}
if(include('compras')||include('ventas'))for(let kind of ['compra','venta'])if(include(kind==='compra'?'compras':'ventas')){let list=invs.filter(i=>i.kind===kind),total=list.reduce((a,i)=>a+i.total,0),tax=list.reduce((a,i)=>a+i.vat,0);sections.push(`<div class="panel table-wrap"><h2>Registro de ${kind==='compra'?'Compras':'Ventas'} (reporte manual demostrativo)</h2><table><tr><th>Fecha</th><th>NIT</th><th>Razón social</th><th>Factura</th><th class="num">Total</th><th class="num">IVA</th></tr>${list.map(i=>`<tr><td>${fmtDate(i.date)}</td><td>${esc(i.nit)}</td><td>${esc(i.third)}</td><td>${esc(i.number)}</td><td class="num">${money(i.total)}</td><td class="num">${money(i.vat)}</td></tr>`).join('')}<tr class="total-row"><td colspan="4">Totales</td><td class="num">${money(total)}</td><td class="num">${money(tax)}</td></tr></table><small class="muted">No genera archivo oficial ni se conecta con SIAT/SIN.</small></div>`)}
if(include('tax')){let buys=invs.filter(i=>i.kind==='compra'),sales=invs.filter(i=>i.kind==='venta'),debit=sales.reduce((a,i)=>a+i.vat,0),credit=buys.reduce((a,i)=>a+i.vat,0),itBase=sales.reduce((a,i)=>a+i.total,0),it=pct(itBase,param('it'));sections.push(`<div class="panel"><h2>Resumen IVA e IT · Demonstrativo</h2><p>Débito fiscal IVA: <b>Bs ${money(debit)}</b> · Crédito fiscal IVA: <b>Bs ${money(credit)}</b> · ${debit>=credit?'IVA estimado por pagar':'Saldo a favor estimado'}: <b>Bs ${money(Math.abs(debit-credit))}</b></p><p>Ventas facturadas: Bs ${money(itBase)} · IT estimado (${param('it')}%): <b>Bs ${money(it)}</b></p><small class="muted">Cálculo académico basado en facturas capturadas. Verifica los parámetros y reglas aplicables. No se conecta a SIAT/SIN.</small>${activeUser?.role==='consulta'?'':`<div class="actions" style="margin-top:12px">${m?'<button data-post-it>Contabilizar IT de este mes</button>':''}<button data-close-year>Calcular IUE y cierre anual</button></div>`}</div>`)}
if(include('ret'))sections.push(`<div class="panel table-wrap"><h2>Libro de Retenciones</h2><table><tr><th>Fecha</th><th>Tercero</th><th>NIT / CI</th><th>Tipo</th><th>Documento</th><th class="num">Importe</th></tr>${db.retentions.filter(r=>inPeriod(r.date)).map(r=>`<tr><td>${fmtDate(r.date)}</td><td>${esc(r.third)}</td><td>${esc(r.nit)}</td><td>${r.type}</td><td>${esc(r.doc)}</td><td class="num">${money(r.amount)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Sin retenciones.</td></tr>'}</table></div>`);
result.innerHTML=sections.join('');window.lastReportCsv=reportRows(type,y,m)}
function postIT(year,month){if(!month)return toast('Elige un mes específico para contabilizar el IT.');let period=`${year}-${String(month).padStart(2,'0')}`,origin=`impuesto-it:${period}`;if(db.vouchers.some(v=>v.origin===origin))return toast('El IT de ese periodo ya fue contabilizado.');let total=db.invoices.filter(i=>i.kind==='venta'&&i.date.startsWith(period)).reduce((a,i)=>a+i.total,0),amount=pct(total,param('it'));if(!amount)return toast('No hay ventas facturadas en el mes.');let last=new Date(year,month,0).getDate(),date=`${period}-${String(last).padStart(2,'0')}`;try{mkVoucher({date,type:'traspaso',glosa:`Provisión IT ${monthName(year,month)}`,origin,lines:[{accountId:account('5.2.08').id,debit:amount,credit:0,note:'Gasto IT'},{accountId:account('2.1.03').id,debit:0,credit:amount,note:'IT por pagar'}]});save();toast(`IT contabilizado: Bs ${money(amount)}.`,true);makeReport(new FormData($('#report-form')))}catch(e){toast(e.message)}}
function closeYear(year){let date=`${year}-12-31`,origin=`cierre-anual:${year}`;if(db.vouchers.some(v=>v.origin===origin))return toast('El cierre de esta gestión ya fue registrado.');if(!periodOpen(date))return toast('Crea y abre diciembre de esa gestión antes del cierre.');let rows=trial(year),preTax=rows.filter(r=>r.account.type==='ingreso').reduce((s,r)=>s+r.credit-r.debit,0)-rows.filter(r=>r.account.type==='gasto'&&r.account.code!=='5.2.09').reduce((s,r)=>s+r.debit-r.credit,0);let rate=param('iue'),tax=Math.max(0,pct(preTax,rate)),afterTax=preTax-tax,reserve=Math.max(0,pct(afterTax,param('reserva_legal')));try{if(tax&&!db.vouchers.some(v=>v.origin===`iue:${year}`))mkVoucher({date,type:'traspaso',glosa:`Provisión IUE gestión ${year}`,origin:`iue:${year}`,lines:[{accountId:account('5.2.09').id,debit:tax,credit:0,note:'Gasto IUE'},{accountId:account('2.1.04').id,debit:0,credit:tax,note:'IUE por pagar'}]});let allocation=[];if(afterTax>0){allocation.push({accountId:account('3.1.04').id,debit:afterTax,credit:0,note:'Aplicación resultado de gestión'});if(reserve)allocation.push({accountId:account('3.1.02').id,debit:0,credit:reserve,note:'Reserva legal'});if(afterTax-reserve>0)allocation.push({accountId:account('3.1.03').id,debit:0,credit:afterTax-reserve,note:'Resultados acumulados'})}if(allocation.length)mkVoucher({date,type:'traspaso',glosa:`Cierre y distribución de resultados ${year}`,origin,lines:allocation});save();log('Cierre anual','Gestión',year,`Utilidad previa Bs ${money(preTax)}; IUE Bs ${money(tax)}; reserva Bs ${money(reserve)}`);toast(`Cierre registrado. IUE Bs ${money(tax)} · Utilidad neta Bs ${money(afterTax)} · Reserva legal Bs ${money(reserve)}.`,true);makeReport(new FormData($('#report-form')))}catch(e){toast(e.message)}}
function reportRows(type,y,m){let rows=[['Informe','Periodo','Cuenta','Debe Bs','Haber Bs','Saldo Bs']];for(let r of trial())if(r.debit||r.credit)rows.push([type,`${m||'Año'}-${y}`,`${r.account.code} ${r.account.name}`,(r.debit/100).toFixed(2),(r.credit/100).toFixed(2),(r.balance/100).toFixed(2)]);return rows}
function csvReport(){let tables=[...document.querySelectorAll('#report-result table')];if(!tables.length)return toast('Primero genera un informe.');let rows=[];for(let table of tables){if(rows.length)rows.push([]);for(let tr of table.rows)rows.push([...tr.cells].map(c=>c.innerText.trim()))}let text=rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\r\n');download(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}),'informe-contable.csv')}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function bindLogin(){if(cloudConfigured){$('#login-id-label').childNodes[0].textContent='Correo electrónico';$('#login-user').type='email';$('#login-user').autocomplete='email';$('#login-help').textContent='Usa el correo y la contraseña que el administrador creó en Supabase.'}$('#login-form').onsubmit=async e=>{e.preventDefault();$('#login-error').textContent='';if(cloudConfigured){if(!window.supabase?.createClient){$('#login-error').textContent='No se cargó la conexión. Revisa internet e inténtalo otra vez.';return}try{cloud=window.supabase.createClient(cloudCfg.url,cloudCfg.publishableKey);setSync('Conectando…');let {data,error}=await cloud.auth.signInWithPassword({email:val('#login-user'),password:val('#login-pass')});if(error)throw error;await startCloudSession(data.user)}catch(err){$('#login-error').textContent=err.message||'No se pudo iniciar sesión.';setSync('Sin conectar')}return}let u=db.users.find(x=>x.username===val('#login-user')&&x.password===val('#login-pass')&&x.active);if(!u){$('#login-error').textContent='Usuario o contraseña incorrectos.';return}activeUser=u;sessionStorage.setItem('contademo_user',u.username);$('#login').classList.add('hidden');$('#app').classList.remove('hidden');navInit();log('Inicio de sesión','Usuario',0,u.username);showPage('inicio')};$('#logout').onclick=async()=>{if(realtimeChannel&&cloud)await cloud.removeChannel(realtimeChannel);if(cloudConfigured&&cloud)await cloud.auth.signOut();cloudReady=false;activeUser=null;sessionStorage.removeItem('contademo_user');$('#app').classList.add('hidden');$('#login').classList.remove('hidden');setSync(cloudConfigured?'Desconectado':'Datos locales')}}
async function restore(){if(cloudConfigured){if(!window.supabase?.createClient)return;cloud=window.supabase.createClient(cloudCfg.url,cloudCfg.publishableKey);let {data}=await cloud.auth.getSession();if(data?.session)await startCloudSession(data.session.user);return}let username=sessionStorage.getItem('contademo_user'),u=db.users.find(x=>x.username===username&&x.active);if(u){activeUser=u;$('#login').classList.add('hidden');$('#app').classList.remove('hidden');navInit();showPage('inicio')}}
function boot(){setSync(cloudConfigured?'Conexión Supabase configurada':'Datos locales');bindLogin();restore()}boot();
})();
